CREATE TABLE public.biedingen (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), object_id uuid NOT NULL, relatie_id uuid NOT NULL, deal_id uuid, object_pipeline_id uuid, counter_offer_to_id uuid, bedrag bigint, currency text NOT NULL DEFAULT 'EUR', bieddatum date NOT NULL DEFAULT CURRENT_DATE, geldig_tot date, status public.biedingstatus NOT NULL DEFAULT 'concept', offer_type public.biedingtype NOT NULL DEFAULT 'indicatief', financieringsvoorbehoud public.voorbehoud_status NOT NULL DEFAULT 'onbekend', dd_voorbehoud public.voorbehoud_status NOT NULL DEFAULT 'onbekend', gewenste_levering date, gewenste_levering_tekst text, waarborgsom_bedrag bigint, waarborgsom_pct numeric, kosten_type text, voorwaarden text, notities text, interne_notities text, bron text, is_best_offer boolean NOT NULL DEFAULT false, is_final_offer boolean NOT NULL DEFAULT false, rejected_reason text, accepted_at timestamptz, rejected_at timestamptz, withdrawn_at timestamptz, expired_at timestamptz, aangemaakt_door uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX idx_biedingen_object ON public.biedingen(object_id); CREATE INDEX idx_biedingen_relatie ON public.biedingen(relatie_id); CREATE INDEX idx_biedingen_deal ON public.biedingen(deal_id); CREATE INDEX idx_biedingen_status ON public.biedingen(status); CREATE INDEX idx_biedingen_pipeline ON public.biedingen(object_pipeline_id); CREATE INDEX idx_biedingen_counter ON public.biedingen(counter_offer_to_id); ALTER TABLE public.biedingen ENABLE ROW LEVEL SECURITY; CREATE POLICY "Intern leest biedingen" ON public.biedingen FOR SELECT TO authenticated USING (is_intern_gebruiker(auth.uid())); CREATE POLICY "Intern voegt biedingen toe" ON public.biedingen FOR INSERT TO authenticated WITH CHECK (is_intern_gebruiker(auth.uid())); CREATE POLICY "Intern wijzigt biedingen" ON public.biedingen FOR UPDATE TO authenticated USING (is_intern_gebruiker(auth.uid())); CREATE POLICY "Intern verwijdert biedingen" ON public.biedingen FOR DELETE TO authenticated USING (is_intern_gebruiker(auth.uid())); CREATE TRIGGER update_biedingen_updated_at BEFORE UPDATE ON public.biedingen FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.kadaster_data_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), object_id uuid NULL REFERENCES public.objecten(id) ON DELETE SET NULL, signaal_id uuid NULL REFERENCES public.off_market_signalen(id) ON DELETE SET NULL, source text NOT NULL DEFAULT 'kadaster_objectinformatie_api', mode text NOT NULL DEFAULT 'kadaster', product_code text NOT NULL, status text NOT NULL, zoekadres jsonb NOT NULL DEFAULT '{}'::jsonb, fetched_at timestamptz NOT NULL DEFAULT now(), koopsom bigint NULL, koopjaar int NULL, koopsom_valuta text NULL, meer_onroerend_goed boolean NULL, doelbinding boolean NULL, bag_bouwjaar int NULL, bag_oppervlakte int NULL, bag_object_status text NULL, bag_gebruiksdoel text NULL, woz_objectnummer text NULL, woz_oppervlakte int NULL, woz_oppervlakte_wonen int NULL, woz_oppervlakte_niet_wonen int NULL, woz_inhoud int NULL, woz_gebruiksklasse text NULL, feitelijk_gebruik text NULL, monumentaanduiding text NULL, actualiteit text NULL, rechten_samenvatting jsonb NULL, rechthebbende_naam text NULL, rechthebbende_type text NULL, rechtsoort text NULL, aandeel text NULL, kadastrale_aanduiding text NULL, raw_limited jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid NULL REFERENCES auth.users(id) ON DELETE SET NULL, CONSTRAINT kadaster_data_records_target_check CHECK (object_id IS NOT NULL OR signaal_id IS NOT NULL), CONSTRAINT kadaster_data_records_product_code_check CHECK (product_code <> ''), CONSTRAINT kadaster_data_records_status_check CHECK (status IN ('geleverd','gedeeltelijk','niet_geleverd','niet_beschikbaar','fout'))); GRANT SELECT,INSERT,UPDATE ON public.kadaster_data_records TO authenticated; GRANT ALL ON public.kadaster_data_records TO service_role; ALTER TABLE public.kadaster_data_records ENABLE ROW LEVEL SECURITY; CREATE POLICY "Interne gebruikers kunnen kadaster-records bekijken" ON public.kadaster_data_records FOR SELECT TO authenticated USING (public.is_intern_gebruiker(auth.uid())); CREATE POLICY "Interne gebruikers kunnen kadaster-records toevoegen" ON public.kadaster_data_records FOR INSERT TO authenticated WITH CHECK (public.is_intern_gebruiker(auth.uid())); CREATE POLICY "Interne gebruikers kunnen kadaster-records bijwerken" ON public.kadaster_data_records FOR UPDATE TO authenticated USING (public.is_intern_gebruiker(auth.uid())) WITH CHECK (public.is_intern_gebruiker(auth.uid())); CREATE INDEX idx_kadaster_records_object_id ON public.kadaster_data_records(object_id) WHERE object_id IS NOT NULL; CREATE INDEX idx_kadaster_records_signaal_id ON public.kadaster_data_records(signaal_id) WHERE signaal_id IS NOT NULL; CREATE INDEX idx_kadaster_records_object_product_fetched ON public.kadaster_data_records(object_id,product_code,fetched_at DESC) WHERE object_id IS NOT NULL; CREATE INDEX idx_kadaster_records_signaal_product_fetched ON public.kadaster_data_records(signaal_id,product_code,fetched_at DESC) WHERE signaal_id IS NOT NULL; CREATE INDEX idx_kadaster_records_fetched_at ON public.kadaster_data_records(fetched_at DESC); CREATE TRIGGER update_kadaster_data_records_updated_at BEFORE UPDATE ON public.kadaster_data_records FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.kadaster_documenten (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), object_id uuid REFERENCES public.objecten(id) ON DELETE SET NULL, signaal_id uuid REFERENCES public.off_market_signalen(id) ON DELETE SET NULL, kadaster_data_record_id uuid REFERENCES public.kadaster_data_records(id) ON DELETE SET NULL, source text NOT NULL DEFAULT 'kadaster_objectinformatie_api', product_codes text[] NOT NULL DEFAULT '{}', zoekadres jsonb NOT NULL DEFAULT '{}'::jsonb, fetched_at timestamptz NOT NULL DEFAULT now(), storage_bucket text NOT NULL DEFAULT 'bito-objecten', storage_path text NOT NULL, bestandsnaam text NOT NULL, bestandsgrootte_bytes bigint, mime_type text NOT NULL DEFAULT 'application/pdf', intern_only boolean NOT NULL DEFAULT true, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT kadaster_documenten_target_check CHECK (object_id IS NOT NULL OR signaal_id IS NOT NULL)); CREATE INDEX idx_kadaster_documenten_object_id ON public.kadaster_documenten(object_id) WHERE object_id IS NOT NULL; CREATE INDEX idx_kadaster_documenten_signaal_id ON public.kadaster_documenten(signaal_id) WHERE signaal_id IS NOT NULL; CREATE INDEX idx_kadaster_documenten_record_id ON public.kadaster_documenten(kadaster_data_record_id) WHERE kadaster_data_record_id IS NOT NULL; GRANT SELECT,INSERT,UPDATE,DELETE ON public.kadaster_documenten TO authenticated; GRANT ALL ON public.kadaster_documenten TO service_role; ALTER TABLE public.kadaster_documenten ENABLE ROW LEVEL SECURITY; CREATE POLICY "Interne gebruikers kunnen kadaster-documenten bekijken" ON public.kadaster_documenten FOR SELECT TO authenticated USING (public.is_intern_gebruiker(auth.uid())); CREATE POLICY "Interne gebruikers kunnen kadaster-documenten toevoegen" ON public.kadaster_documenten FOR INSERT TO authenticated WITH CHECK (public.is_intern_gebruiker(auth.uid())); CREATE POLICY "Interne gebruikers kunnen kadaster-documenten bijwerken" ON public.kadaster_documenten FOR UPDATE TO authenticated USING (public.is_intern_gebruiker(auth.uid())) WITH CHECK (public.is_intern_gebruiker(auth.uid())); CREATE POLICY "Interne gebruikers kunnen kadaster-documenten verwijderen" ON public.kadaster_documenten FOR DELETE TO authenticated USING (public.is_intern_gebruiker(auth.uid())); CREATE TRIGGER update_kadaster_documenten_updated_at BEFORE UPDATE ON public.kadaster_documenten FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column(); ALTER TABLE public.kadaster_data_records ADD COLUMN IF NOT EXISTS pdf_document_id uuid REFERENCES public.kadaster_documenten(id) ON DELETE SET NULL; CREATE INDEX IF NOT EXISTS idx_kadaster_records_pdf_document_id ON public.kadaster_data_records(pdf_document_id) WHERE pdf_document_id IS NOT NULL;